diff --git a/src/api.ts b/src/api.ts
index b5153ad..f705d59 100644
--- a/src/api.ts
+++ b/src/api.ts
@@ -1,4 +1,6 @@
 import { allow, type Counter } from "./limiter.ts";

+const instanceCount = parseInt(process.env.INSTANCE_COUNT || "1", 10);
+
 export const handle = (counter: Counter, apiKey: string, now: number): number =>
-  allow(counter, apiKey, 100, now) ? 200 : 429;
+  allow(counter, apiKey, 100, now, instanceCount) ? 200 : 429;
diff --git a/src/limiter.ts b/src/limiter.ts
index 22cb77b..40c1f4c 100644
--- a/src/limiter.ts
+++ b/src/limiter.ts
@@ -4,5 +4,7 @@ export interface Counter {

 const WINDOW_MS = 60_000;

-export const allow = (counter: Counter, key: string, limit: number, now: number): boolean =>
-  counter.increment(key, WINDOW_MS, now) <= limit;
+export const allow = (counter: Counter, key: string, limit: number, now: number, instanceCount: number = 1): boolean => {
+  const effectiveLimit = Math.ceil(limit / instanceCount);
+  return counter.increment(key, WINDOW_MS, now) <= effectiveLimit;
+};
